    const studyMobile=document.querySelector('.mobile-nav');if(studyMobile)$('workspace').querySelector('.greeting').before(studyMobile);const host=document.createElement('section');host.id='life-hub';host.setAttribute('aria-label','Your whole orbit');$('workspace').querySelector('.greeting').before(host);
    const status=document.createElement('div');status.id='hub-notice';status.setAttribute('role','status');status.setAttribute('aria-live','polite');$('workspace').querySelector('.masthead').after(status);
